SELECT FifoStock.Prdt, [1ISIN].SYM, FifoStock.fDate AS [Receiving Date], FifoStock.PQty AS [Purchased Qty], FifoStock.AvQty AS [In Stock], FifoStock.Rt AS Rate, [rt]/[pqty] AS PriceM, ([Rt]/[PQty]*[AvQty]) AS [Value], Realtick.[HSTCLSDATE ( LIVEQUOTE )], Realtick.[HST_CLOSE ( LIVEQUOTE )] AS PriceR, [1Currency].Currency, [value]/IIf([Currency]="EUR",1,[Change]![C_LAST_PRICE_REF ( LIVEQUOTE )]) AS Valueâ‚¬, IIf([Currency]="EUR",1,[Change]![C_LAST_PRICE_REF ( LIVEQUOTE )]) AS Change, Realtick.[C_LAST_PRICE_REF ( LIVEQUOTE )] AS Live, ([live]*[AvQty]) AS ValueLive, [ValueLive]/[change] AS ValueLiveâ‚¬, [MTD]/[change] AS ValueMTDâ‚¬, [pricemtd]*[avqty] AS MTD, [Realtick]![CLOSE_1M_TD ( SECURITY )] AS PriceMTD, [Realtick]![CLOSE_1W_TD ( SECURITY )] AS PriceWTD, Realtick.[BID_DATE ( LIVEQUOTE )], [1ISIN].IdS, [1ISIN].IdA, [1ISIN].IdD, [1ISIN].IdT, [1ISIN].IdR, [1Sector].Sector, [1Assett].[Assett class], [1Direction].Direction, [1Type].Type, [1Region].Region, [1ISIN].Leverage, ([Valueliveâ‚¬])*[leverage] AS ValLeverage, Change.IdC, qStrategy.TT, qStrategy.UltimoDiDate, Realtick.[BETA ( SECURITY )] AS Beta, IIf([Beta]=0,IIf([1ISIN]![IdD]=3,-1,1),IIf([Beta] Is Null,IIf([1ISIN]![IdD]=3,-1,1),[Beta])) AS BetaN, [Valueliveâ‚¬]*[betaN] AS BetaPon, [1ISIN].Quote
FROM (Change INNER JOIN ((((((Realtick RIGHT JOIN ((FifoStock INNER JOIN 1ISIN ON FifoStock.Prdt = [1ISIN].ISIN) LEFT JOIN 1Currency ON [1ISIN].IdC = [1Currency].IdC) ON Realtick.[ISIN_NO ( LIVEQUOTE )] = [1ISIN].ISIN) LEFT JOIN 1Assett ON [1ISIN].IdA = [1Assett].IdA) LEFT JOIN 1Direction ON [1ISIN].IdD = [1Direction].IdD) LEFT JOIN 1Region ON [1ISIN].IdR = [1Region].IdR) LEFT JOIN 1Sector ON [1ISIN].IdS = [1Sector].IdS) LEFT JOIN 1Type ON [1ISIN].IdT = [1Type].IdT) ON Change.IdC = [1ISIN].IdC) LEFT JOIN qStrategy ON [1ISIN].ISIN = qStrategy.ISIN;
